using System;
using System.IO;
using System.Linq;
using System.Drawing;
using System.Windows.Forms;
using System.Collections.Generic;
using System.Diagnostics;
using System.Runtime.InteropServices;
using System.Web.Script.Serialization;
namespace MonitorSlice {
static class FrameBench {
 [DllImport("MonitorSlice.Capture.dll",CallingConvention=CallingConvention.Cdecl)]static extern int StartAnimation(IntPtr window,out IntPtr handle);
 [DllImport("MonitorSlice.Capture.dll",CallingConvention=CallingConvention.Cdecl)]static extern ulong CaptureFrames(IntPtr handle);
 [DllImport("MonitorSlice.Capture.dll",CallingConvention=CallingConvention.Cdecl)]static extern void StopCapture(IntPtr handle);
 public static void RunGpu(){var records=new List<object>();var session=new VirtualSession();session.Recover();var target=Screen.AllScreens.First(s=>!Displays.Virtual().Any(v=>v.Name==s.DeviceName)).Bounds;try{foreach(var key in new[]{"full","cols","grid"}){var forms=new List<Form>();var animations=new List<IntPtr>();try{session.Start(target,Layouts.Create(key),false);foreach(var v in session.Views){var f=new Form{AutoScaleMode=AutoScaleMode.None,Bounds=v.Source,FormBorderStyle=FormBorderStyle.None,StartPosition=FormStartPosition.Manual,TopMost=true,ShowInTaskbar=false};f.Show();Native.ShowWindowAsync(f.Handle,5);Native.SetWindowPos(f.Handle,new IntPtr(-1),v.Source.X,v.Source.Y,v.Source.Width,v.Source.Height,0x210);forms.Add(f);IntPtr animation;Marshal.ThrowExceptionForHR(StartAnimation(f.Handle,out animation));animations.Add(animation);}Wait(700);for(int i=0;i<forms.Count;i++){var area=session.Views[i].Source;Native.SetWindowPos(forms[i].Handle,new IntPtr(-1),area.X,area.Y,area.Width,area.Height,0x210);}session.RaiseOutput();Wait(300);var before=animations.Select(a=>CaptureFrames(a)).ToArray();var output=session.PerViewFrames;var received=session.Received;var watch=Stopwatch.StartNew();Wait(4000);double seconds=watch.Elapsed.TotalSeconds;records.Add(new{layout=key,backend=session.Backend,seconds=seconds,producerFps=animations.Select((a,i)=>(CaptureFrames(a)-before[i])/seconds).ToArray(),captureReceivedPerViewFps=(session.Received-received)/seconds/animations.Count,outputRequestsPerViewFps=session.PerViewFrames.Select((value,i)=>(value-output[i])/seconds).ToArray(),frameAgeMs=session.FrameAgeMs,errors=session.RenderErrors});}finally{foreach(var a in animations)StopCapture(a);foreach(var f in forms)f.Close();session.Stop();}}}finally{session.Stop();File.WriteAllText(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"evidence",Environment.CommandLine.Contains("--no-capture")?"gpu-frame-bench-no-capture.json":"gpu-frame-bench.json"),new JavaScriptSerializer().Serialize(new{recordedAt=DateTime.UtcNow.ToString("o"),scope="Independent D3D11 continuously changing source windows, four second sample. Counts producer/capture/present requests, not physical scanout.",records=records}));}}
 static void Wait(int ms){var watch=Stopwatch.StartNew();do{Application.DoEvents();System.Threading.Thread.Sleep(1);}while(watch.ElapsedMilliseconds<ms);}
 static Color Pixel(Point p){using(var b=new Bitmap(1,1))using(var g=Graphics.FromImage(b)){g.CopyFromScreen(p,Point.Empty,b.Size);return b.GetPixel(0,0);}}
 public static void Run(){var records=new List<object>();var session=new VirtualSession();session.Recover();var target=Screen.AllScreens.First(s=>!Displays.Virtual().Any(v=>v.Name==s.DeviceName)).Bounds;
 try{foreach(var key in new[]{"full","cols","grid"}){var forms=new List<Form>();try{session.Start(target,Layouts.Create(key),false);foreach(var v in session.Views){var f=new Form{AutoScaleMode=AutoScaleMode.None,Bounds=v.Source,FormBorderStyle=FormBorderStyle.None,StartPosition=FormStartPosition.Manual,TopMost=true,ShowInTaskbar=false,BackColor=Color.Black};f.Show();forms.Add(f);}Wait(700);var samples=new List<double>();int missed=0;var total=Stopwatch.StartNew();ulong before=session.Frames;for(int n=0;n<24;n++){var color=Color.FromArgb(20+(n*53)%220,20+(n*79)%220,20+(n*31)%220);foreach(var f in forms){f.BackColor=color;f.Update();}var watch=Stopwatch.StartNew();bool match=false;while(watch.ElapsedMilliseconds<600){Wait(1);match=session.Views.All(v=>{var c=Pixel(new Point(v.Destination.X+35,v.Destination.Y+35));return Math.Abs(c.R-color.R)+Math.Abs(c.G-color.G)+Math.Abs(c.B-color.B)<15;});if(match)break;}samples.Add(watch.Elapsed.TotalMilliseconds);if(!match)missed++;Wait(16);}records.Add(new{layout=key,backend=session.Backend,views=forms.Count,frameAgeAtReceiptMs=session.FrameAgeMs,missed=missed,averageMs=samples.Average(),maxMs=samples.Max(),p95Ms=samples.OrderBy(x=>x).ElementAt((int)(samples.Count*.95)),distinctStepsPerSecond=(24-missed)/total.Elapsed.TotalSeconds,outputRequestsPerViewPerSecond=(session.Frames-before)/(double)forms.Count/total.Elapsed.TotalSeconds,errors=session.RenderErrors});}finally{foreach(var f in forms)f.Close();session.Stop();}}}finally{session.Stop();string backend=Environment.CommandLine.Contains("--gdi-output")?"gdi":"wgc";File.WriteAllText(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"evidence","frame-bench-"+backend+".json"),new JavaScriptSerializer().Serialize(new{recordedAt=DateTime.UtcNow.ToString("o"),backend=backend,scope="24 distinct color changes per layout, physical output pixel confirmation. Includes CopyFromScreen measurement overhead; not a game benchmark.",records=records}));}}
}
}
